-- Nouveaux articles du 24/11/2026 (SEO : services à la personne et facture électronique), créés en BROUILLON.
-- À exécuter dans Supabase → SQL Editor (projet de l'application). Ensuite, dans le back-office (rubrique Articles) :
-- relire chaque article, choisir sa date de parution, le publier, puis « Mettre en ligne ».
-- Sans effet si un article du même slug existe déjà. Le complément de l'article clôture ne s'ajoute qu'une fois.

begin;

insert into public.blog_posts (slug, title, excerpt, keywords, summary, body, links, status, reading_minutes) values (
  'avance-immediate-credit-impot-jardinage',
  'Avance immédiate et jardinage : le guide du paysagiste',
  'Avance immédiate du crédit d’impôt pour le jardinage : comment elle fonctionne, ce qu’elle change pour vos clients et comment la proposer.',
  array['avance immédiate jardinage', 'avance immédiate crédit d’impôt', 'crédit d’impôt jardinage', 'services à la personne paysagiste']::text[],
  array['Avec l’avance immédiate, votre client particulier ne paie que la moitié de vos prestations de jardinage en services à la personne : le crédit d’impôt est déduit tout de suite.', 'Le service est géré par l’Urssaf : vous déclarez la prestation, le client la valide en ligne, puis l’Urssaf vous verse le montant total.', 'Il faut être déclaré en services à la personne et passer par l’espace Urssaf ou par un logiciel ou un intermédiaire habilité.', 'Les règles du crédit d’impôt ne changent pas : 50 % des sommes versées, dans la limite de 5 000 € de dépenses de jardinage par an et par foyer.']::text[],
  '[{"paragraphs": ["Pour beaucoup de clients, le crédit d’impôt jardinage a un défaut : il faut avancer toute la somme et attendre l’année suivante pour récupérer la moitié. L’avance immédiate supprime cette attente. Voici comment elle fonctionne et ce qu’elle change pour un paysagiste déclaré en services à la personne."]}, {"heading": "L’avance immédiate, c’est quoi ?", "paragraphs": ["C’est un service de l’Urssaf, ouvert depuis 2022 aux services à la personne. Au lieu de payer 100 % de la prestation puis de déclarer la dépense aux impôts, le client paie directement sa part, après déduction du crédit d’impôt.", "Exemple : pour 200 € de tonte et de taille de haie, le client sans avance immédiate paie 200 € et récupère 100 € l’année suivante. Avec l’avance immédiate, il ne paie que 100 €."]}, {"heading": "Comment fonctionne l’avance immédiate, étape par étape", "list": ["Vous inscrivez votre client au service ; il active son espace particulier sur le site de l’Urssaf.", "Après l’intervention, vous déclarez la prestation et son montant.", "Le client reçoit une notification et dispose de quelques jours pour la valider ou la contester ; sans réponse, elle est considérée comme validée.", "L’Urssaf prélève au client sa part, puis vous verse le montant total de la prestation."]}, {"heading": "Quelles prestations de jardinage sont concernées ?", "paragraphs": ["Les mêmes que pour le crédit d’impôt : les petits travaux de jardinage chez un particulier, couverts par votre déclaration SAP (tonte, taille de haies et d’arbustes, désherbage, ramassage des feuilles). Les travaux de création, comme une terrasse, une clôture ou la plantation d’un nouveau jardin, n’y ouvrent pas droit.", "Le plafond reste celui du jardinage : 5 000 € de dépenses par an et par foyer, soit 2 500 € de crédit d’impôt au maximum. Les montants peuvent évoluer : vérifiez-les chaque année sur impots.gouv.fr."]}, {"heading": "Ce que l’avance immédiate change pour un paysagiste", "list": ["Un argument commercial fort : le client voit tout de suite le prix réel qu’il paiera.", "Des clients qui hésitaient à avancer la somme acceptent plus facilement un contrat d’entretien à l’année.", "Une démarche de plus : chaque prestation doit être déclarée, et le paiement passe par l’Urssaf.", "Une trésorerie qui dépend de la validation du client et du versement de l’Urssaf."]}, {"heading": "Comment proposer l’avance immédiate à vos clients", "paragraphs": ["Il faut d’abord être déclaré en services à la personne. Ensuite, deux possibilités : déclarer vos prestations vous-même sur l’espace de l’Urssaf, ou passer par un logiciel ou une plateforme habilités à le faire pour vous. Renseignez-vous sur le site de l’Urssaf, rubrique avance immédiate, pour les conditions à jour.", "Dans tous les cas, gardez des devis et des factures clairs, qui distinguent les prestations SAP du reste : c’est ce qui rend les montants déclarés faciles à justifier."]}, {"heading": "Et avec Paysapro AI ?", "paragraphs": ["Paysapro AI ne gère pas l’avance immédiate : il ne déclare pas les prestations à l’Urssaf. Il vous aide en amont et en aval : devis qui repèrent les prestations SAP et reprennent votre numéro de déclaration, suivi des règlements, et attestation fiscale annuelle générée en PDF pour les clients qui ne passent pas par l’avance immédiate."]}]'::jsonb,
  '[{"label": "Logiciel paysagiste et services à la personne", "to": "/logiciel-paysagiste-services-a-la-personne"}, {"label": "Attestation fiscale SAP jardinage : le guide", "to": "/blog/attestation-fiscale-sap-jardinage"}, {"label": "Contrat d’entretien de jardin : que prévoir ?", "to": "/blog/contrat-entretien-jardin"}]'::jsonb,
  'draft',
  5
) on conflict (slug) do nothing;

insert into public.blog_posts (slug, title, excerpt, keywords, summary, body, links, status, reading_minutes) values (
  'plateforme-agreee-facture-electronique',
  'Plateforme agréée : comment choisir la sienne avant 2027',
  'Plateforme agréée de facture électronique : à quoi elle sert, pourquoi il en faut une dès maintenant et les critères pour choisir la vôtre avant 2027.',
  array['plateforme agréée', 'choisir plateforme agréée', 'facture électronique artisan', 'facture électronique paysagiste']::text[],
  array['Une plateforme agréée par l’administration transmet vos factures électroniques à vos clients professionnels et déclare les données au fisc.', 'Depuis le 1er septembre 2026, toute entreprise doit pouvoir recevoir des factures électroniques : il faut donc déjà une plateforme pour la réception.', 'Le portail public ne permet pas d’émettre des factures : chaque entreprise choisit une plateforme agréée.', 'Les bons critères : le prix, la compatibilité avec votre logiciel de facturation, la réception, l’e-reporting et l’archivage.']::text[],
  '[{"paragraphs": ["Avec la réforme de la facture électronique, une facture entre professionnels ne partira plus par simple e-mail : elle passera par une plateforme agréée. Pour un artisan ou un paysagiste, le choix de cette plateforme est la vraie décision à prendre avant septembre 2027. Voici comment s’y retrouver."]}, {"heading": "À quoi sert une plateforme agréée ?", "list": ["Recevoir les factures électroniques de vos fournisseurs.", "Transmettre vos factures à vos clients professionnels, sur leur propre plateforme.", "Déclarer à l’administration les données de vos factures et, pour les ventes aux particuliers, celles de vos opérations (e-reporting).", "Suivre le statut de chaque facture : déposée, reçue, refusée, payée."]}, {"heading": "Pourquoi en choisir une dès maintenant", "paragraphs": ["Depuis le 1er septembre 2026, toutes les entreprises, micro-entreprises comprises, doivent pouvoir recevoir des factures électroniques. L’émission devient obligatoire pour les TPE et PME le 1er septembre 2027. Choisir sa plateforme tôt laisse le temps de la tester sur les factures reçues avant d’y faire passer les vôtres.", "Le portail public de facturation ne propose pas d’émission de factures : il sert d’annuaire et transmet les données à l’administration. Chaque entreprise doit donc passer par une plateforme agréée. La liste officielle est publiée sur impots.gouv.fr."]}, {"heading": "Les critères pour choisir sa plateforme agréée", "list": ["Le prix : abonnement mensuel, prix par facture ou offre comprise dans un autre service (banque, expert-comptable, logiciel).", "La compatibilité avec votre logiciel de facturation : peut-il lui envoyer directement vos factures au format Factur-X, UBL ou CII ?", "La réception : les factures de vos fournisseurs sont-elles lisibles simplement, et exportables vers votre comptabilité ?", "L’e-reporting : la plateforme déclare-t-elle aussi vos ventes aux particuliers et vos encaissements ?", "L’archivage : combien de temps vos factures sont-elles conservées, et pouvez-vous les récupérer si vous changez de plateforme ?", "L’accompagnement : un service client joignable, en français, au moment où une facture est refusée."]}, {"heading": "Format et plateforme : deux choses différentes", "paragraphs": ["Le format, c’est la façon dont la facture est écrite : Factur-X, UBL ou CII. La plateforme, c’est le canal par lequel elle circule. Votre logiciel de facturation produit le format ; la plateforme le transmet. Un logiciel qui produit déjà un format accepté vous évite de ressaisir vos factures sur la plateforme."]}, {"heading": "Demandez conseil à votre expert-comptable", "paragraphs": ["Beaucoup de cabinets comptables proposent ou recommandent une plateforme, déjà reliée à leurs outils. C’est souvent le choix le plus simple : vos factures arrivent directement chez celui qui tient votre comptabilité."]}, {"heading": "Où en est Paysapro AI", "paragraphs": ["Paysapro AI produit déjà chaque facture, facture d’acompte et avoir au format Factur-X, profil EN 16931. Le raccordement à une plateforme agréée est en préparation pour l’échéance de septembre 2027, pour que vos factures partent sans ressaisie."]}]'::jsonb,
  '[{"label": "Facture électronique : ce qui change pour les paysagistes", "to": "/facture-electronique-paysagiste"}, {"label": "Logiciel de facture électronique Factur-X", "to": "/logiciel-facture-electronique"}, {"label": "Factur-X : la facture électronique expliquée aux artisans", "to": "/blog/factur-x-artisan"}]'::jsonb,
  'draft',
  5
) on conflict (slug) do nothing;

-- Article « Comment calculer le prix d’une clôture ? » (position 19 à 27 sur « prix clôture grillage ») : ajoute une partie sur le grillage.
update public.blog_posts set
  body = body || jsonb_build_array('{"heading": "Clôture en grillage : le calcul du prix", "paragraphs": ["Le grillage soudé ou simple torsion se vend en rouleaux, souvent de 25 m : nombre de rouleaux = longueur à clôturer ÷ longueur d’un rouleau, arrondi à l’entier supérieur. Comptez les poteaux avec un entraxe de 2 à 2,5 m, plus une jambe de force à chaque angle et à chaque extrémité, et ajoutez fil de tension, tendeurs et ligatures.", "Exemple : 60 m de grillage donnent 3 rouleaux de 25 m et 25 poteaux. Additionnez fournitures, scellements, main-d’œuvre et préparation du terrain, puis divisez par la longueur pour obtenir votre prix au mètre linéaire posé. Le [calculateur de clôture](/outils/calcul-cloture) fait le comptage pour vous."]}'::jsonb),
  display_updated_at = current_date
where slug = 'calculer-prix-cloture'
  and not exists (select 1 from jsonb_array_elements(body) e where e->>'heading' = 'Clôture en grillage : le calcul du prix');

commit;
